//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			HE_OxygenControl                                                                                                                                                                                                                                                                           
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE				SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0				2025-03-04		William Veim			Initial release                                                                                                                                                                                                                                  
//	1.0.1				2025-04-23		Ruben Byman			Bugfix, added missing process value to PID
//	1.0.2				2025-04-29		Ruben Byman			Added 4th sensor input, bug fix state control, added alarm trigger and suppression
//	1.1.0				2025-09-10		William Veim			Removed input "Cfg_ControlCabinet"
//	1.1.1				2025-09-15		William Veim			Bugfix PWM valve output
//	1.1.2				2025-11-20		William Veim			Overwrite I and D time 2min after startup
//	1.1.3				2026-04-24		William Veim			Bugfix emergency oxygen time interval windup
//	1.1.4				2026-05-22		Ruben Byman			Added INT structure for outputs
//
//===============================================================================================================================
//
//		DESCRIPTION:    
// 		Oxygen Control in Fish Tanks
//		Uses a base dosing valve, PWM valve, control valve, and/or emergency valve as actuators.
// 		The base dosing valve remains open as long as AMA=2.
// 		Sets the desired oxygen saturation (%) in the tank. In automatic mode, the regulator adjusts the output to maintain a stable setpoint.
// 		Configurable parameters in SCADA include P, I, and D values, setpoint, cycle time (for the PWM valve), minimum on-time (PWM valve), and minimum off-time (PWM valve).
//		
//==============================================================================================================================

 (*************************************************************************
 *	INITIALIZE VARIABELS
 *************************************************************************)
 
 Ext_OxygenControl.EXT_General.LocationIndex[0]:=Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA
 Ext_OxygenControl.EXT_General.MainDosing_Visible:=Cfg_MainValve_InUse;
 Ext_OxygenControl.EXT_General.PWMControl_Visible:=Cfg_PWM_InUse;
 Ext_OxygenControl.EXT_General.EmergencyControl_Visible:=Cfg_EmergencyValve_InUse;
 Ext_OxygenControl.EXT_Alarm.Sts_SupressIfOff_Visible:=TRUE;
 Ext_OxygenControl.EXT_General.Controlled_FromController:=Cfg_ControllerName;
 DtToDateStruct(In:=GetTime(), DateStruct=>DateStruct);
	
 IF NOT Ext_OxygenControl.INT_Data.Initialise THEN
	
	//Operator settings
	Ext_OxygenControl.EXT_Operator.SP_Actual.ProcessValue:=90;
	
	//Engeneering settings
	Ext_OxygenControl.EXT_Engineering.EmergencyValve_Delay:=10;
	Ext_OxygenControl.EXT_Engineering.EmergencyValve_Setpoint:=80;
	Ext_OxygenControl.EXT_Engineering.EmergencyValve_TimeInterval_Duration:=2;
	Ext_OxygenControl.EXT_Engineering.EmergencyValve_TimeInterval_Hours:=12;
	Ext_OxygenControl.EXT_Engineering.PID_P_band:=100;
	Ext_OxygenControl.EXT_Engineering.PID_I_time:=250;
	Ext_OxygenControl.EXT_Engineering.PID_D_time:=0;
	Ext_OxygenControl.EXT_Engineering.PV_AutoSwitchState:=2;
	Ext_OxygenControl.EXT_Engineering.PWM_CycleTime:=30;
	
	//State config
	Ext_OxygenControl.EXT_Engineering.StateCfg_1.Cfg_Quality:=3; //Process value not available = Warning
	Ext_OxygenControl.EXT_Engineering.StateCfg_1.Cfg_Alarm:=TRUE; //Process value not available = Alarm
	Ext_OxygenControl.EXT_Engineering.StateCfg_2.Cfg_Quality:=0; //Configuration fault = Diagnostic
	Ext_OxygenControl.EXT_Engineering.StateCfg_2.Cfg_Alarm:=TRUE; //Configuration fault = Alarm
	Ext_OxygenControl.EXT_Engineering.StateCfg_3.Cfg_Quality:=0; //Interlock = Diagnostic
	Ext_OxygenControl.EXT_Engineering.StateCfg_3.Cfg_Alarm:=TRUE; //Interlock = Alarm
	
	//Alarm settings
	Ext_OxygenControl.EXT_Alarm.Cfg_SupressDelayOff:=10;
	Ext_OxygenControl.EXT_Alarm.Cfg_AlarmActiveDelay:=10;
	Ext_OxygenControl.EXT_Alarm.Cfg_AlarmReturnDelay:=10;
	
	//Init complete
	Ext_OxygenControl.INT_Data.Initialise:=TRUE;
	
END_IF;

(*************************************************************************
 *	UPDATING PROCESS VALUE
 *************************************************************************)
 
 HE_PV_Select(EXT_AnalogValue:=Ext_AnalogValue, 
						 PV_Select:=Ext_OxygenControl.EXT_Operator.PV_Select, 
						 PV_AutoSwitch:=Ext_OxygenControl.EXT_Engineering.PV_AutoSwitch, 
						 PV_AutoSwitchState:=Ext_OxygenControl.EXT_Engineering.PV_AutoSwitchState, 
						 PV_Actual=>Ext_OxygenControl.EXT_Operator.PV_Actual, 
						 PV_Actual_Y0=>Wrk_PV_Actual_Y0, 
						 PV_Actual_Y1=>Wrk_PV_Actual_Y1, 
						 PV_NotAvailable=>Wrk_PVNotAvailable, 
						 PV_NumberUsed=>Wrk_NumberPVUsed, 
						 PV_MultipleUsed=>Ext_OxygenControl.EXT_General.PV_ValueChange_Visible, 
						 PV_Value1_Index:=Ext_OxygenControl.EXT_Engineering.Cfg_PV_Value1, 
						 PV_Value2_Index:=Ext_OxygenControl.EXT_Engineering.Cfg_PV_Value2, 
						 PV_Value3_Index:=Ext_OxygenControl.EXT_Engineering.Cfg_PV_Value3, 
						 PV_Value4_Index:=Ext_OxygenControl.EXT_Engineering.Cfg_PV_Value4, 
						 PV_Value5_Index:=Ext_OxygenControl.EXT_Engineering.Cfg_PV_Value5);

Ext_OxygenControl.EXT_Engineering.PWM_MinOnTime:=LIMIT(MN:=UINT#0, 
																										In:=Ext_OxygenControl.EXT_Engineering.PWM_MinOnTime, 
																										MX:=Ext_OxygenControl.EXT_Engineering.PWM_CycleTime);

(*************************************************************************
 *	PID CONTROL
 *************************************************************************)

FB_PID(ENS:=Ext_OxygenControl.EXT_Operator.Mode > 0, 
		Cfg_RetainOutput:=TRUE, 
		Inp_ManualControl:=FALSE,//Not in use (yet) 
		Inp_ManualValue:=0,//Not in use (yet) 
		Inp_Proportional_Band:=Ext_OxygenControl.EXT_Engineering.PID_P_band, 
		Inp_IntergrationTime:=Ext_OxygenControl.EXT_Engineering.PID_I_time, 
		Inp_DerivationTime:=Ext_OxygenControl.EXT_Engineering.PID_D_time, 
		ProcessValue:=Ext_OxygenControl.EXT_Operator.PV_Actual.ProcessValue, 
		SetpointValue:=Ext_OxygenControl.EXT_Operator.SP_Actual.ProcessValue,  
		RngUpLmt:=Wrk_PV_Actual_Y1, 
		RngLowLmt:=Wrk_PV_Actual_Y0, 
		MVLowLmt:=0, 
		MVUpLmt:=100, 
		Direction:=FALSE,
		Autotune_Start:=Dummy,
		Output=>Wrk_AutoGain);

(*************************************************************************
 *	CASE FOR CONTROL MODE
 *************************************************************************)
 
IF NOT Inp_Interlock THEN
	CASE Ext_OxygenControl.EXT_Operator.Mode OF

		0: //OFF
		Wrk_Gain :=								0;
		Wrk_Emergency_Valve :=			FALSE;
		Wrk_MainDosing_Valve :=		FALSE;
		Wrk_PWM_Valve := 					FALSE;
		Ext_OxygenControl.EXT_Operator.PWM_OnTime :=	0;
		Ext_OxygenControl.EXT_Operator.PWM_OffTime :=	0;
		
		2: //AUTO
		
		//Sets gain for analog valve
		Wrk_Gain := Wrk_AutoGain;
		
		//Opens main dosing valve
		Wrk_MainDosing_Valve := TRUE;
		
		// Calculates "ON time" for pulse-width modulation (PWM) based on output demand and cycle time
		Ext_OxygenControl.EXT_Operator.PWM_OnTime:=REAL_TO_UINT(ScaleTrans(SclIn:=Wrk_AutoGain, 
						X0:=0.0, 
						Y0:=0.0, 
						X1:=100.0, 
						Y1:=Ext_OxygenControl.EXT_Engineering.PWM_CycleTime));

		// Calculates "OFF time" for pulse-width modulation (PWM) based on cycle time and ON time
		Ext_OxygenControl.EXT_Operator.PWM_OffTime:=Ext_OxygenControl.EXT_Engineering.PWM_CycleTime - Ext_OxygenControl.EXT_Operator.PWM_OnTime;
		
		// Timers for pulse-width modulation (PWM)
		TON_CycleTime(PT:=SecToTime(In:=Ext_OxygenControl.EXT_Engineering.PWM_CycleTime));
		TP_OnTime(PT:=SecToTime(In:=Ext_OxygenControl.EXT_Operator.PWM_OnTime+Ext_OxygenControl.EXT_Engineering.PWM_MinOnTime), Q=>Wrk_PWM_Valve);
		
		// Start of timer for pulse-width modulation (PWM)
		IF TON_CycleTime.Q THEN
			TON_CycleTime.In := FALSE;
			TP_OnTime.In := FALSE;
		ELSE
			TON_CycleTime.In := TRUE;
			TP_OnTime.In := TRUE;
		END_IF;
		
		// Initiates delay timer before engaging the emergency valve
		TON_Emergency_Valve(PT:=SecToTime(Ext_OxygenControl.EXT_Engineering.EmergencyValve_Delay));
		IF FB_PID.Processvalue <= Ext_OxygenControl.EXT_Engineering.EmergencyValve_Setpoint THEN
			TON_Emergency_Valve.In := TRUE;
		ELSE 
			TON_Emergency_Valve.In := FALSE;
		END_IF;
		
		// Interval counter between forced valve openings
		TON_EmergencyValve_TimeInterval(PT:=SecToTime(Ext_OxygenControl.EXT_Engineering.EmergencyValve_TimeInterval_Hours * 3600));
		TOF_EmergencyValve_TimeInterval(PT:=SecToTime(Ext_OxygenControl.EXT_Engineering.EmergencyValve_TimeInterval_Duration));
		
		IF Ext_OxygenControl.EXT_Engineering.EmergencyValve_TimeInterval_Activate THEN
			TON_EmergencyValve_TimeInterval.In :=TRUE;
			IF TON_EmergencyValve_TimeInterval.Q THEN
				TOF_EmergencyValve_TimeInterval.In :=TRUE;
			ELSE
				TOF_EmergencyValve_TimeInterval.In :=FALSE;
			END_IF;
			IF TOF_EmergencyValve_TimeInterval.Q THEN
				TON_EmergencyValve_TimeInterval.In := FALSE;
			END_IF;
		ELSE 
			TON_EmergencyValve_TimeInterval.In :=FALSE;
			TOF_EmergencyValve_TimeInterval.In:=FALSE;
		END_IF;
		
		Wrk_Emergency_Valve:=TON_Emergency_Valve.Q OR TOF_EmergencyValve_TimeInterval.Q;
		
	END_CASE;

ELSE //Interlocked
	
	Wrk_Gain:=0;
	Wrk_MainDosing_Valve:=FALSE;
	Ext_OxygenControl.EXT_Operator.PWM_OffTime:=0;
	Ext_OxygenControl.EXT_Operator.PWM_OnTime:=0;
	
END_IF;

(*************************************************************************
 *	STATE CONTROL
 *************************************************************************)

//FAULT CONTROL
//---------------------------
Wrk_Interlock:= Inp_Interlock;

								//PV value not set
Wrk_ConfigFault:=(			 Ext_OxygenControl.EXT_Engineering.Cfg_PV_Value1=0
								AND Ext_OxygenControl.EXT_Engineering.Cfg_PV_Value2=0
								AND Ext_OxygenControl.EXT_Engineering.Cfg_PV_Value3=0
								AND Ext_OxygenControl.EXT_Engineering.Cfg_PV_Value4=0
								AND Ext_OxygenControl.EXT_Engineering.Cfg_PV_Value5=0)
								
								//PID parameter not set
								OR Ext_OxygenControl.EXT_Engineering.PID_P_band = 0
								AND Ext_OxygenControl.EXT_Engineering.PID_I_time= 0 
								AND Ext_OxygenControl.EXT_Engineering.PID_D_time=0
								
								//PWM used and no cycle time
								OR Ext_OxygenControl.EXT_General.PWMControl_Visible
								AND Ext_OxygenControl.EXT_Engineering.PWM_CycleTime=0;
								
//Resetter variabler før løkke
Ext_OxygenControl.EXT_General.Sts_Quality :=  6; //Good
Wrk_ActionState:=	0;

//STATE 1 - No process value available
HE_StateControl(EXT_StateData:=Ext_OxygenControl.EXT_Engineering.StateCfg_1, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Wrk_PVNotAvailable, 
							Inp_Desc:='Process value not available', 
							Sts_Quality:=Ext_OxygenControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[0].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[0].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[0].Alm_Priority);
			
//STATE 2 - Configuration fault
HE_StateControl(EXT_StateData:=Ext_OxygenControl.EXT_Engineering.StateCfg_2, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Wrk_ConfigFault, 
							Inp_Desc:='Configuration fault', 
							Sts_Quality:=Ext_OxygenControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[1].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[1].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[1].Alm_Priority);

//STATE 3 - Interlock
HE_StateControl(EXT_StateData:=Ext_OxygenControl.EXT_Engineering.StateCfg_3, 
							Inp_Visibility:=Cfg_Interlock_InUse, 
							Inp_State:=Wrk_Interlock, 
							Inp_Desc:='Interlock', 
							Sts_Quality:=Ext_OxygenControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[2].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[2].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[2].Alm_Priority);

CASE Wrk_ActionState OF
	
	0://Use value
	Ext_OxygenControl.EXT_Operator.Actual_Gain:= Wrk_Gain;
	
	1://Hold value
	Ext_OxygenControl.EXT_Operator.Actual_Gain:=Ext_OxygenControl.EXT_Operator.Actual_Gain;
	
	2://Pre defined output
	Ext_OxygenControl.EXT_Operator.Actual_Gain:=Ext_OxygenControl.EXT_Engineering.StateCfg_PreDefinedOutput;
	
	3://OFF
	Ext_OxygenControl.EXT_Operator.Actual_Gain:=0;
	
END_CASE;		
								
(*************************************************************************
 *	ALARM CONTROL
 *************************************************************************)

//Supress if off mode
IF Ext_OxygenControl.EXT_Alarm.Sts_SupressIfOff_Visible AND Ext_OxygenControl.EXT_Alarm.Cfg_SupressIfOff AND Ext_OxygenControl.EXT_Operator.Mode = 0 THEN
	FB_AlarmLogic.Inp_AlarmSupress:=TRUE;
	FB_AlarmLogic.Inp_AlmSuppressDesc:= 'Off mode';
//Supress from FB input
ELSIF Inp_AlmSuppress THEN
	FB_AlarmLogic.Inp_AlarmSupress:=TRUE;
	FB_AlarmLogic.Inp_AlmSuppressDesc:= Inp_AlmSuppressDesc;
ELSE
	FB_AlarmLogic.Inp_AlarmSupress:=FALSE;
	FB_AlarmLogic.Inp_AlmSuppressDesc:= '';
END_IF;

(*************************************************************************
 *	EXCECUTING ALARM BLOCK
 *************************************************************************)
 
 FB_AlarmLogic(ENS:=TRUE, 
								 Ext_Alarm:=Ext_OxygenControl.EXT_Alarm, 
								 Int_Alarm:=Int_Alarm, 
								 Inp_AlarmData:=Wrk_AlarmData,
								 Inp_LocationData:=Ext_OxygenControl.EXT_General.LocationIndex,
								 Inp_Connected_Cabinet:='', 
								 Inp_Connected_Controller:=Cfg_ControllerName, 
								 Inp_Process_TAG:='',
								 Inp_Process_Value:= '',
								 Inp_Process_Desc:=Ext_OxygenControl.EXT_General.Process_Desc,
								 Out_AlarmToken=>Wrk_AlarmToken, 
								 Out_AlarmTriggered=>Wrk_AlarmTriggered);

(*************************************************************************
 *	STATISTIC DATA
 *************************************************************************)

RE_Minute(Clk:=Get1minClk());

IF RE_Minute.Q AND Ext_OxygenControl.EXT_Operator.Mode = 2 THEN
	
	//Process value at setpoint
	IF Ext_OxygenControl.EXT_Operator.SP_Actual.ProcessValue > Ext_OxygenControl.EXT_Operator.PV_Actual.ProcessValue * 1.1 OR Ext_OxygenControl.EXT_Operator.SP_Actual.ProcessValue < Ext_OxygenControl.EXT_Operator.PV_Actual.ProcessValue * 0.9 THEN
		Inc(Ext_OxygenControl.EXT_Statistics.TimeToday_AtSetpoint);
	//Prosess value under setpoint
	ELSIF Ext_OxygenControl.EXT_Operator.SP_Actual.ProcessValue < Ext_OxygenControl.EXT_Operator.PV_Actual.ProcessValue * 0.91 THEN
		Inc(Ext_OxygenControl.EXT_Statistics.TimeToday_UnderSetpoint);
	//Prosess value over setpoint
	ELSIF Ext_OxygenControl.EXT_Operator.SP_Actual.ProcessValue > Ext_OxygenControl.EXT_Operator.PV_Actual.ProcessValue * 0.11 THEN
		Inc(Ext_OxygenControl.EXT_Statistics.TimeToday_OverSetpoint);
	END_IF;
	
END_IF;

IF Sample_Day <> DateStruct.Day THEN
	Ext_OxygenControl.EXT_Statistics.TimeToday_AtSetpoint := 0;
	Ext_OxygenControl.EXT_Statistics.TimeToday_UnderSetpoint := 0;
	Ext_OxygenControl.EXT_Statistics.TimeToday_OverSetpoint := 0;
	Sample_Day := DateStruct.Day;
END_IF;

  (*************************************************************************
 *	UPDATING OUTPUT
 *************************************************************************)
  //Updating output to FB block
  Out_ActuatorData_OxCtrl.MainDosingValve := 		Wrk_MainDosing_Valve;
  Out_ActuatorData_OxCtrl.PWM:= 							Wrk_PWM_Valve;
  Out_ActuatorData_OxCtrl.EmergencyValve:= 			Wrk_Emergency_Valve;
  Out_ActuatorData_OxCtrl.ControlValve:= 				Ext_OxygenControl.EXT_Operator.Actual_Gain;
  Sts_Alarm:=	Wrk_AlarmTriggered;
 
 //Updating structure
Ext_OxygenControl.EXT_Operator.PWMValve_Status:= 					Wrk_PWM_Valve;
Ext_OxygenControl.EXT_Operator.MainDosingValve_Status:= 		Wrk_MainDosing_Valve;
Ext_OxygenControl.EXT_Operator.EmergencyVale_Status:= 			Wrk_Emergency_Valve;
Ext_OxygenControl.EXT_Operator.SP_Actual.Process_Desc := 		'Setpoint';
Ext_OxygenControl.EXT_Operator.SP_Actual.Process_Unit := 		Ext_OxygenControl.EXT_Operator.PV_Actual.Process_Unit;
